import{_ as t,o as n,c as i,a2 as e}from"./chunks/framework.BZO4qERu.js";const f=JSON.parse('{"title":"画布 (Canvas)","description":"","frontmatter":{},"headers":[],"relativePath":"canvas.md","filePath":"canvas.md","lastUpdated":1669882888000}'),o={name:"canvas.md"};function s(d,a,l,r,p,c){return n(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="画布-canvas" tabindex="-1">画布 (Canvas)</h1><hr><p style="font:italic 1em sans-serif;color:#78909C;">此章节待补充或完善...</p><p style="font:italic 1em sans-serif;color:#78909C;">Marked by SuperMonster003 on Oct 22, 2022.</p><hr><p>canvas提供了使用画布进行2D画图的支持, 可用于简单的小游戏开发或者图片编辑. 使用canvas可以轻松地在一张图片或一个界面上绘制各种线与图形.</p><p>canvas的坐标系为平面直角坐标系, 以控件左上角为原点, 控件上边沿为x轴正方向, 控件左边沿为y轴正方向. 例如分辨率为1920*1080的屏幕上, canvas控件覆盖全屏, 画一条从屏幕左上角到屏幕右下角的线段为:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>canvas.drawLine(0, 0, 1080, 1920, paint);</span></span></code></pre></div><p>canvas的绘制依赖于画笔Paint, 通过设置画笔的粗细、颜色、填充等可以改变绘制出来的图形. 例如绘制一个红色实心正方形为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var paint = new Paint();</span></span>
<span class="line"><span>//设置画笔为填充, 则绘制出来的图形都是实心的</span></span>
<span class="line"><span>paint.setStyle(Paint.STYLE.FILL);</span></span>
<span class="line"><span>//设置画笔颜色为红色</span></span>
<span class="line"><span>paint.setColor(colors.RED);</span></span>
<span class="line"><span>//绘制一个从坐标(0, 0)到坐标(100, 100)的正方形</span></span>
<span class="line"><span>canvas.drawRect(0, 0, 100, 100, paint);</span></span></code></pre></div><p>如果要绘制正方形的边框, 则通过设置画笔的Style来实现：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>var paint = new Paint();</span></span>
<span class="line"><span>//设置画笔为描边, 则绘制出来的图形都是轮廓</span></span>
<span class="line"><span>paint.setStyle(Paint.STYLE.STROKE);</span></span>
<span class="line"><span>//设置画笔颜色为红色</span></span>
<span class="line"><span>paint.setColor(colors.RED);</span></span>
<span class="line"><span>//绘制一个从坐标(0, 0)到坐标(100, 100)的正方形</span></span>
<span class="line"><span>canvas.drawRect(0, 0, 100, 100, paint);</span></span></code></pre></div><p>结合画笔, canvas可以绘制基本图形、图片等.</p><h2 id="canvas-getwidth" tabindex="-1">canvas.getWidth()</h2><ul><li>返回 {number}</li></ul><p>返回画布当前图层的宽度.</p><h2 id="canvas-getheight" tabindex="-1">canvas.getHeight()</h2><ul><li>返回 {number}</li></ul><p>返回画布当前图层的高度.</p><h2 id="canvas-drawrgb-r-int-g-int-b" tabindex="-1">canvas.drawRGB(r, int g, int b)</h2><ul><li><code>r</code> {number} 红色通道值</li><li><code>g</code> {number} 绿色通道值</li><li><code>b</code> {number} 蓝色通道值</li></ul><p>将整个可绘制区域填充为r、g、b指定的颜色. 相当于 <code>canvas.drawColor(colors.rgb(r, g, b))</code>.</p><h2 id="canvas-drawargb-a-r-g-b" tabindex="-1">canvas.drawARGB(a, r, g, b)</h2><ul><li><code>a</code> {number} 透明通道值</li><li><code>r</code> {number} 红色通道值</li><li><code>g</code> {number} 绿色通道值</li><li><code>b</code> {number} 蓝色通道值</li></ul><p>将整个可绘制区域填充为a、r、g、b指定的颜色. 相当于 <code>canvas.drawColor(colors.argb(a, r, g, b))</code>.</p><h2 id="canvas-drawcolor-color" tabindex="-1">canvas.drawColor(color)</h2><ul><li><code>color</code> {number} 颜色值</li></ul><p>将整个可绘制区域填充为color指定的颜色.</p><h2 id="canvas-drawcolor-color-mode" tabindex="-1">canvas.drawColor(color, mode)</h2><ul><li><code>color</code> {number} 颜色值</li><li><code>mode</code> {PorterDuff.Mode} Porter-Duff操作</li></ul><p>将整个可绘制区域填充为color指定的颜色.</p><h2 id="canvas-drawpaint-paint" tabindex="-1">canvas.drawPaint(paint)</h2><ul><li><code>paint</code> {Paint} 画笔</li></ul><p>将整个可绘制区域用paint指定的画笔填充. 相当于绘制一个无限大的矩形, 但是更快. 通过该方法可以绘制一个指定的着色器的图案.</p><h2 id="canvas-drawpoint-x-y-paint" tabindex="-1">canvas.drawPoint(x, y, paint)</h2><ul><li><code>x</code> {number} x坐标</li><li><code>y</code> {number} y坐标</li><li><code>paint</code> {Paint} 画笔</li></ul><p>在可绘制区域绘制由坐标(x, y)指定的点. 点的形状由画笔的线帽决定（参见paint.setStrokeCap(cap)）. 点的大小由画笔的宽度决定（参见paint.setStrokeWidth(width)）.</p><blockquote><p>如果画笔宽度为0, 则也会绘制1个像素至4个（若抗锯齿启用）.</p></blockquote><p>相当于 <code>canvas.drawPoints([x, y], paint)</code>.</p><h2 id="canvas-drawpoints-pts-paint" tabindex="-1">canvas.drawPoints(pts, paint)</h2><ul><li><code>pts</code> {Array&lt;number&gt;} 点坐标数组 [x0, y0, x1, y1, x2, y2, ...]</li><li><code>paint</code> {Paint} 画笔</li></ul><p>在可绘制区域绘制由坐标数组指定的多个点.</p><h2 id="canvas-drawline-startx-starty-stopx-stopy-paint" tabindex="-1">canvas.drawLine(startX, startY, stopX, stopY, paint)</h2><ul><li><code>startX</code> {number} 起点x坐标</li><li><code>startY</code> {number} 起点y坐标</li><li><code>endX</code> {number} 终点x坐标</li><li><code>endY</code> {number} 终点y坐标</li><li><code>paint</code> {Paint} 画笔</li></ul><p>在可绘制区域绘制由起点坐标(startX, startY)和终点坐标(endX, endY)指定的线. 绘制时会忽略画笔的样式(Style). 也就是说, 即使样式设为“仅填充(FILL)”也会绘制. 退化为点的线（长度为0）不会被绘制.</p><h2 id="canvas-drawrect-r-paint" tabindex="-1">canvas.drawRect(r, paint)</h2><ul><li><code>r</code> {Rect} 矩形边界</li><li><code>paint</code> {Paint} 画笔</li></ul><p>在可绘制区域绘制由矩形边界r指定的矩形. 绘制时画笔的样式(Style)决定了是否绘制矩形界线和填充矩形.</p><h2 id="canvas-drawrect-left-top-right-bottom-android-graphics-paint-paint" tabindex="-1">canvas.drawRect(left, top, right, bottom, android.graphics.Paint paint)</h2><ul><li><code>left</code> {number} 矩形左边界x坐标</li><li><code>top</code> {number} 矩形上边界y坐标</li><li><code>right</code> {number} 矩形右边界x坐标</li><li><code>bottom</code> {number} 矩形下边界y坐标</li><li><code>paint</code> {Paint} 画笔</li></ul><p>在可绘制区域绘制由矩形边界(left, top, right, bottom)指定的矩形. 绘制时画笔的样式(Style)决定了是否绘制矩形界线和填充矩形.</p><h2 id="canvas-drawoval-android-graphics-rectf-oval-android-graphics-paint-paint" tabindex="-1">canvas.drawOval(android.graphics.RectF oval, android.graphics.Paint paint)</h2><h2 id="canvas-drawoval-float-left-float-top-float-right-float-bottom-android-graphics-paint-paint" tabindex="-1">canvas.drawOval(float left, float top, float right, float bottom, android.graphics.Paint paint)</h2><h2 id="canvas-drawcircle-float-cx-float-cy-float-radius-android-graphics-paint-paint" tabindex="-1">canvas.drawCircle(float cx, float cy, float radius, android.graphics.Paint paint)</h2><h2 id="canvas-drawarc-android-graphics-rectf-oval-float-startangle-float-sweepangle-boolean-usecenter-android-graphics-paint-paint" tabindex="-1">canvas.drawArc(android.graphics.RectF oval, float startAngle, float sweepAngle, boolean useCenter, android.graphics.Paint paint)</h2><h2 id="canvas-drawarc-float-left-float-top-float-right-float-bottom-float-startangle-float-sweepangle-boolean-usecenter-android-graphics-paint-paint" tabindex="-1">canvas.drawArc(float left, float top, float right, float bottom, float startAngle, float sweepAngle, boolean useCenter, android.graphics.Paint paint)</h2><h2 id="canvas-drawroundrect-android-graphics-rectf-rect-float-rx-float-ry-android-graphics-paint-paint" tabindex="-1">canvas.drawRoundRect(android.graphics.RectF rect, float rx, float ry, android.graphics.Paint paint)</h2><h2 id="canvas-drawroundrect-float-left-float-top-float-right-float-bottom-float-rx-float-ry-android-graphics-paint-paint" tabindex="-1">canvas.drawRoundRect(float left, float top, float right, float bottom, float rx, float ry, android.graphics.Paint paint)</h2><h2 id="canvas-drawpath-android-graphics-path-path-android-graphics-paint-paint" tabindex="-1">canvas.drawPath(android.graphics.Path path, android.graphics.Paint paint)</h2><h2 id="canvas-drawbitmap-android-graphics-bitmap-bitmap-float-left-float-top-android-graphics-paint-paint" tabindex="-1">canvas.drawBitmap(android.graphics.Bitmap bitmap, float left, float top, android.graphics.Paint paint)</h2><h2 id="canvas-drawtext-java-lang-string-text-float-x-float-y-android-graphics-paint-paint" tabindex="-1">canvas.drawText(java.lang.String text, float x, float y, android.graphics.Paint paint)</h2><h2 id="canvas-drawtextonpath-java-lang-string-text-android-graphics-path-path-float-hoffset-float-voffset-android-graphics-paint-paint" tabindex="-1">canvas.drawTextOnPath(java.lang.String text, android.graphics.Path path, float hOffset, float vOffset, android.graphics.Paint paint)</h2><h2 id="canvas-translate-dx-dy" tabindex="-1">canvas.translate(dx, dy)</h2><ul><li><code>dx</code> {number} 向x轴正方向平移的距离, 负数表示反方向平移</li><li><code>dy</code> {number} 向y轴正方向平移的距离, 负数表示反方向平移</li></ul><p>平移指定距离.</p><h2 id="canvas-scale-sx-sy" tabindex="-1">canvas.scale(sx, sy)</h2><ul><li><code>sx</code> {number} 向x轴正方向平移的距离, 负数表示反方向平移</li><li><code>sy</code> {number} 向y轴正方向平移的距离, 负数表示反方向平移</li></ul><p>以原点为中心, 将坐标系平移缩放指定倍数.</p><h2 id="canvas-scale-float-sx-float-sy-float-px-float-py" tabindex="-1">canvas.scale(float sx, float sy, float px, float py)</h2><h2 id="canvas-rotate-float-degrees" tabindex="-1">canvas.rotate(float degrees)</h2><h2 id="canvas-rotate-float-degrees-float-px-float-py" tabindex="-1">canvas.rotate(float degrees, float px, float py)</h2><h2 id="canvas-skew-float-sx-float-sy" tabindex="-1">canvas.skew(float sx, float sy)</h2><h1 id="画笔" tabindex="-1">画笔</h1><h1 id="变换矩阵" tabindex="-1">变换矩阵</h1><h1 id="路径" tabindex="-1">路径</h1><h1 id="porter-duff操作" tabindex="-1">Porter-Duff操作</h1><h1 id="着色器" tabindex="-1">着色器</h1><h1 id="遮罩过滤器" tabindex="-1">遮罩过滤器</h1><h1 id="颜色过滤器" tabindex="-1">颜色过滤器</h1><h1 id="路径特效" tabindex="-1">路径特效</h1><h1 id="区域" tabindex="-1">区域</h1>`,81)])])}const b=t(o,[["render",s]]);export{f as __pageData,b as default};
